update tbl_talent
	set category_seq = #{categorySeq}, title = #{title}, content = #{content}, price = #{price}
	where talent_seq = #{talentSeq}
		and expert_seq = #{expertSeq}
		and enabled = 'Y'

update tbl_talent
	set enabled = 'N'
	where talent_seq = #{talentSeq}
		and expert_seq = #{expertSeq}
		and enabled = 'Y'

